<div class="mb-4"><h1 class="h3">Administration dashboard</h1><p class="text-secondary">Account and category totals by status.</p></div><div class="row g-3"><div class="col-lg-8"><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Role</th><th>Active</th><th>Inactive</th></tr></thead><tbody><?php foreach (['Administrator', 'IT Manager', 'IT Support', 'Employee'] as $role): $active = $inactive = 0; foreach ($counts as $row) if ($row['role'] === $role) { if ($row['is_active']) $active = $row['total']; else $inactive = $row['total']; } ?><tr><td><?= esc($role) ?></td><td><?= (int) $active ?></td><td><?= (int) $inactive ?></td></tr><?php endforeach ?></tbody></table></div></div></div><div class="col-lg-4"><div class="card"><div class="card-header">Ticket categories</div><div class="card-body"><dl class="row mb-0"><?php $activeCategories = $inactiveCategories = 0; foreach ($categoryCounts as $row) { if ($row['is_active']) $activeCategories = $row['total']; else $inactiveCategories = $row['total']; } ?><dt class="col">Active</dt><dd class="col-auto"><?= (int) $activeCategories ?></dd><dt class="col">Inactive</dt><dd class="col-auto"><?= (int) $inactiveCategories ?></dd></dl></div></div></div></div>
